const botMessages = ['Hello! I can surely help you with that.', 'AI is the field of creating intelligent machines that can perform tasks that typically require human intelligence, such as visual perception, speech recognition, decision-making, and language translation.'];

// Function to handle chat message sending
function sendMessage() {
