  // Send message to bot API (simulated)
  const botResponse = botMessages.shift();
  if (botResponse) {
    // Display bot message
    displayChatMessage('Bot', botResponse);
  } else {
    // Close modal if bot has no more messages
    M.Modal.getInstance(document.querySelector('#chatModal')).close();
  }
}

// Trigger modal
const chatModalTrigger = document.getElementById('chatModalTrigger');
chatModalTrigger.addEventListener('click', () => {
  M.Modal.trigger(document.querySelector('#chatModal'));
